using UnityEngine;

/// <summary>
/// Simple first/third-person player movement using CharacterController.
/// Supports WASD movement, jumping, sprinting, and mouse look.
/// </summary>
[RequireComponent(typeof(CharacterController))]
public class PlayerMovement : MonoBehaviour
{
    [Header("Movement")]
    [SerializeField] private float walkSpeed = 5f;
    [SerializeField] private float sprintSpeed = 10f;
    [SerializeField] private float acceleration = 10f;
    [SerializeField] private float airControl = 0.3f;

    [Header("Jumping & Gravity")]
    [SerializeField] private float jumpHeight = 2f;
    [SerializeField] private float gravity = -9.81f;
    [SerializeField] private float groundCheckDistance = 0.2f;
    [SerializeField] private LayerMask groundMask = ~0;

    [Header("Camera Look")]
    [SerializeField] private Camera playerCamera;
    [SerializeField] private float mouseSensitivity = 2f;
    [SerializeField] private Vector2 pitchClamp = new Vector2(-90f, 90f);
    [SerializeField] private bool lockCursor = true;

    [Header("Keybinds")]
    [SerializeField] private KeyCode jumpKey = KeyCode.Space;
    [SerializeField] private KeyCode sprintKey = KeyCode.LeftShift;

    // Components
    private CharacterController _controller;
    private Transform _cameraTransform;

    // State
    private Vector3 _currentVelocity;
    private float _verticalVelocity;
    private float _yaw;
    private float _pitch;
    private bool _isGrounded;

    private void Awake()
    {
        _controller = GetComponent<CharacterController>();

        if (playerCamera == null)
            playerCamera = Camera.main;

        if (playerCamera != null)
            _cameraTransform = playerCamera.transform;
    }

    private void Start()
    {
        if (lockCursor)
        {
            Cursor.lockState = CursorLockMode.Locked;
            Cursor.visible = false;
        }
    }

    private void Update()
    {
        HandleMouseLook();
        HandleMovement();
    }

    private void HandleMouseLook()
    {
        if (playerCamera == null) return;

        float mouseX = Input.GetAxis("Mouse X") * mouseSensitivity;
        float mouseY = Input.GetAxis("Mouse Y") * mouseSensitivity;

        _yaw += mouseX;
        _pitch -= mouseY;
        _pitch = Mathf.Clamp(_pitch, pitchClamp.x, pitchClamp.y);

        // Rotate the player body horizontally
        transform.rotation = Quaternion.Euler(0f, _yaw, 0f);

        // Rotate the camera vertically
        _cameraTransform.localRotation = Quaternion.Euler(_pitch, 0f, 0f);
    }

    private void HandleMovement()
    {
        // Ground check
        _isGrounded = Physics.CheckSphere(
            transform.position + Vector3.down * (_controller.height * 0.5f - _controller.radius),
            _controller.radius + groundCheckDistance,
            groundMask
        );

        // Get input
        float horizontal = Input.GetAxisRaw("Horizontal");
        float vertical = Input.GetAxisRaw("Vertical");
        Vector3 inputDirection = new Vector3(horizontal, 0f, vertical).normalized;

        // Calculate target direction relative to camera facing
        Vector3 forward = transform.forward;
        Vector3 right = transform.right;
        Vector3 targetDirection = (forward * inputDirection.z + right * inputDirection.x);

        if (targetDirection.magnitude > 0f)
            targetDirection.Normalize();

        // Sprint
        bool isSprinting = Input.GetKey(sprintKey) && inputDirection.z > 0f && _isGrounded;
        float targetSpeed = isSprinting ? sprintSpeed : walkSpeed;

        // Apply acceleration (reduced in air)
        float accelerationFactor = _isGrounded ? acceleration : acceleration * airControl;

        Vector3 targetVelocity = targetDirection * targetSpeed;
        _currentVelocity = Vector3.Lerp(_currentVelocity, targetVelocity, accelerationFactor * Time.deltaTime);

        // Apply horizontal movement
        _controller.Move(_currentVelocity * Time.deltaTime);

        // Jump
        if (Input.GetKeyDown(jumpKey) && _isGrounded)
        {
            _verticalVelocity = Mathf.Sqrt(jumpHeight * -2f * gravity);
        }

        // Apply gravity
        _verticalVelocity += gravity * Time.deltaTime;

        // Reset vertical velocity when grounded to prevent accumulating
        if (_isGrounded && _verticalVelocity < 0f)
        {
            _verticalVelocity = -2f; // Small downward force to stay grounded
        }

        // Apply vertical movement
        _controller.Move(Vector3.up * _verticalVelocity * Time.deltaTime);
    }

    private void OnDrawGizmosSelected()
    {
        // Visualize ground check sphere
        if (_controller != null)
        {
            Gizmos.color = _isGrounded ? Color.green : Color.red;
            Gizmos.DrawWireSphere(
                transform.position + Vector3.down * (_controller.height * 0.5f - _controller.radius),
                _controller.radius + groundCheckDistance
            );
        }
    }
}
```

