using UnityEditor;
using UnityEngine;

public static class CreateCapsule
{
    [MenuItem("Tools/Create Capsule")]
    static void Create()
    {
        // Create capsule at a reasonable position (above terrain, near origin)
        GameObject capsule = GameObject.CreatePrimitive(PrimitiveType.Capsule);
        capsule.name = "Custom Capsule";
        capsule.transform.position = new Vector3(0, 1, 0); // Adjust as needed

        // Select and focus
        Selection.activeGameObject = capsule;
        SceneView.lastActiveSceneView?.FrameSelected();
    }
}
```

